options.css:
* { box-sizing: border-box; margin: 0; padding: 0; }
.erp-root { font-family: 'Inter', 'Segoe UI', -apple-system, sans-serif; background: #f8f9fa; color: #1a1a2e; width: 100%; height: 100%; overflow-y: auto; padding: 0; }
.erp-header { background: #fff; border-bottom: 1px solid #e0e0e0; padding: 16px 32px; display: flex; align-items: center; justify-content: space-between; }
.erp-header-left { display: flex; align-items: center; gap: 16px; }
.erp-logo { width: 32px; height: 32px; background: #0054a6; border-radius: 6px; display: flex; align-items: center; justify-content: center; color: #fff; font-weight: 700; font-size: 14px; }
.erp-title { font-size: 18px; font-weight: 600; color: #1a1a2e; }
.erp-subtitle { font-size: 12px; color: #6b7280; margin-top: 2px; }
.erp-header-right { display: flex; align-items: center; gap: 12px; }
.erp-timestamp { font-size: 11px; color: #9ca3af; }
.erp-body { padding: 24px 32px; }
.erp-kpi-row { display: grid; grid-template-columns: 1.2fr 1fr 1fr 1fr; gap: 16px; margin-bottom: 24px; }
.erp-kpi { background: #fff; border: 1px solid #e5e7eb; border-radius: 8px; padding: 20px; position: relative; overflow: hidden; }
.erp-kpi-label { font-size: 11px; font-weight: 500; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; }
.erp-kpi-value { font-size: 32px; font-weight: 700; color: #1a1a2e; line-height: 1; }
.erp-kpi-value.red { color: #dc2626; }
.erp-kpi-value.green { color: #059669; }
.erp-kpi-value.amber { color: #d97706; }
.erp-kpi-sub { font-size: 12px; color: #6b7280; margin-top: 6px; }
.erp-kpi-badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 500; }
.erp-badge-red { background: #fef2f2; color: #dc2626; }
.erp-badge-green { background: #f0fdf4; color: #059669; }
.erp-kpi-ticker { height: 32px; margin-top: 8px; }
.erp-ticker-bar { display: inline-block; width: 3px; margin-right: 1px; background: #dc2626; border-radius: 1px; vertical-align: bottom; opacity: 0.6; animation: tickerPulse 2s ease-in-out infinite; }
@keyframes tickerPulse { 0%,100% { opacity: 0.4; } 50% { opacity: 0.9; } }
.erp-section { margin-bottom: 24px; }
.erp-section-title { font-size: 14px; font-weight: 600; color: #374151; margin-bottom: 12px; padding-bottom: 8px; border-bottom: 2px solid #e5e7eb; }
.erp-collapsible { cursor: pointer; display: flex; justify-content: space-between; align-items: center; user-select: none; }
.erp-collapsible:hover { color: #0054a6; }
.erp-chevron { font-size: 12px; transition: transform 0.2s; }
.erp-chevron.open { transform: rotate(90deg); }
.erp-collapsed { display: none; }
.erp-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.erp-card { background: #fff; border: 1px solid #e5e7eb; border-radius: 8px; padding: 20px; }
.erp-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.erp-table-sm { font-size: 12px; }
.erp-table th { text-align: left; padding: 8px 12px; font-weight: 500; color: #6b7280; font-size: 11px; text-transform: uppercase; letter-spacing: 0.5px; border-bottom: 2px solid #e5e7eb; background: #f9fafb; }
.erp-table td { padding: 10px 12px; border-bottom: 1px solid #f3f4f6; }
.erp-table tr:hover td { background: #f9fafb; }
.erp-table .num { text-align: right; font-variant-numeric: tabular-nums; }
.erp-table .impact { font-weight: 600; color: #dc2626; }
.erp-table .recovery { font-weight: 500; color: #059669; }
.erp-cat-badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 10px; font-weight: 500; }
.erp-cat-Unplanned { background: #fef2f2; color: #dc2626; }
.erp-cat-External { background: #eff6ff; color: #2563eb; }
.erp-cat-Planned { background: #f0fdf4; color: #059669; }
.erp-cat-Quality { background: #fefce8; color: #ca8a04; }
.erp-cat-Unknown { background: #f3f4f6; color: #6b7280; }
.erp-bar-container { margin-bottom: 4px; }
.erp-bar-header { display: flex; justify-content: space-between; font-size: 13px; margin-bottom: 2px; cursor: pointer; padding: 6px 8px; border-radius: 4px; transition: background 0.15s; }
.erp-bar-header:hover { background: #f3f4f6; }
.erp-bar-header.active { background: #eff6ff; }
.erp-bar-name { color: #374151; font-weight: 600; display: flex; align-items: center; gap: 6px; }
.erp-bar-chevron { font-size: 10px; color: #9ca3af; transition: transform 0.2s; display: inline-block; }
.erp-bar-chevron.open { transform: rotate(90deg); }
.erp-bar-value { color: #6b7280; font-weight: 500; }
.erp-bar-track { height: 20px; background: #f3f4f6; border-radius: 4px; overflow: hidden; margin: 0 8px; }
.erp-bar-fill { height: 100%; border-radius: 4px; display: flex; align-items: center; padding-left: 8px; font-size: 10px; color: #fff; font-weight: 500; }
.erp-bar-reasons { padding-left: 16px; margin: 4px 8px 8px; overflow: hidden; transition: max-height 0.25s ease, opacity 0.2s ease; }
.erp-bar-reasons.collapsed { max-height: 0 !important; opacity: 0; margin: 0 8px; }
.erp-bar-reason { font-size: 11px; color: #6b7280; display: flex; justify-content: space-between; padding: 3px 4px; border-radius: 3px; cursor: pointer; transition: background 0.15s; }
.erp-bar-reason:hover { background: #f3f4f6; }
.erp-bar-reason.active { background: #eff6ff; font-weight: 600; color: #1a1a2e; }
.erp-trend-legend { font-size: 11px; font-weight: 400; color: #9ca3af; }
.erp-trend-row { display: flex; align-items: flex-end; gap: 4px; height: 80px; padding-top: 16px; position: relative; }
.erp-trend-bar { flex: 1; background: #dbeafe; border-radius: 3px 3px 0 0; position: relative; min-height: 4px; transition: height 0.3s; cursor: default; }
.erp-trend-bar.current { background: #0054a6; }
.erp-trend-bar:hover { opacity: 0.8; }
.erp-trend-bar-val { position: absolute; top: -14px; left: 50%; transform: translateX(-50%); font-size: 9px; color: #6b7280; white-space: nowrap; font-weight: 500; }
.erp-trend-labels { display: flex; gap: 4px; font-size: 10px; color: #9ca3af; margin-top: 4px; }
.erp-trend-labels span { flex: 1; text-align: center; }
.erp-trend-reset { margin-top: 8px; font-size: 11px; color: #0054a6; cursor: pointer; text-align: center; font-weight: 500; padding: 4px; border-radius: 4px; }
.erp-trend-reset:hover { background: #eff6ff; }
.erp-footer { padding: 12px 32px; font-size: 11px; color: #9ca3af; border-top: 1px solid #e5e7eb; background: #fff; display: flex; justify-content: space-between; }

options.onInit:
var fmt = function(n) {
  if (n == null || isNaN(n)) return '\u20ac0';
  if (Math.abs(n) >= 1000) return '\u20ac' + (n/1000).toFixed(1) + 'K';
  return '\u20ac' + Math.round(n);
};
var fmtFull = function(n) {
  if (n == null || isNaN(n)) return '\u20ac0';
  return '\u20ac' + Math.round(n).toLocaleString('de-DE');
};
function getField(series, name) {
  if (!series || !series.fields) return null;
  for (var i = 0; i < series.fields.length; i++) {
    if (series.fields[i].name === name) {
      var vals = series.fields[i].values;
      return vals && vals.length > 0 ? vals[0] : null;
    }
  }
  return null;
}
function getRows(series) {
  if (!series || !series.fields || !series.fields.length) return [];
  var len = series.fields[0].values ? series.fields[0].values.length : 0;
  var rows = [];
  for (var r = 0; r < len; r++) {
    var row = {};
    for (var f = 0; f < series.fields.length; f++) {
      row[series.fields[f].name] = series.fields[f].values[r];
    }
    rows.push(row);
  }
  return rows;
}
function findSeries(d, refId) {
  for (var i = 0; i < d.series.length; i++) {
    if (d.series[i].refId === refId) return d.series[i];
  }
  return null;
}

var recoveryRates = {
  'Unplanned': 0.75, 'Quality': 0.85, 'External': 0.25, 'Planned': 0.15, 'Unknown': 0.50
};
var colors = ['#dc2626','#d97706','#0054a6','#059669','#7c3aed','#db2777'];
var monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

var trendFilter = { type: 'all', line: null, reason: null };
var allTrendRows = [];

// ---- Wire up ALL event handlers ONCE, outside _render ----

// Evidence toggle
var etoggle = htmlNode.querySelector('#evidence-toggle');
var ecard = htmlNode.querySelector('#evidence-card');
var echev = htmlNode.querySelector('#evidence-chevron');
if (etoggle) {
  etoggle.addEventListener('click', function() {
    var hidden = ecard.classList.toggle('erp-collapsed');
    echev.classList.toggle('open', !hidden);
  });
}

// Trend reset
var resetBtn = htmlNode.querySelector('#trend-reset');
if (resetBtn) {
  resetBtn.addEventListener('click', function() {
    trendFilter = { type: 'all', line: null, reason: null };
    renderTrend();
    updateDriverHighlights();
  });
}

// Cost drivers: single delegated click handler on the container
var driversEl = htmlNode.querySelector('#cost-drivers');
if (driversEl) {
  driversEl.addEventListener('click', function(e) {
    var target = e.target.closest('[data-action]');
    if (!target) return;
    var action = target.getAttribute('data-action');
    var lineName = target.getAttribute('data-line');

    if (action === 'toggle-line') {
      var reasonsDiv = htmlNode.querySelector('[data-reasons-for="' + lineName + '"]');
      var chevronEl = target.querySelector('.erp-bar-chevron');
      if (reasonsDiv) {
        var wasCollapsed = reasonsDiv.classList.contains('collapsed');
        reasonsDiv.classList.toggle('collapsed');
        if (chevronEl) chevronEl.classList.toggle('open', wasCollapsed);
      }
      if (trendFilter.type === 'line' && trendFilter.line === lineName) {
        trendFilter = { type: 'all', line: null, reason: null };
      } else {
        trendFilter = { type: 'line', line: lineName, reason: null };
      }
      renderTrend();
      updateDriverHighlights();
    } else if (action === 'select-reason') {
      var reasonName = target.getAttribute('data-reason');
      if (trendFilter.type === 'reason' && trendFilter.line === lineName && trendFilter.reason === reasonName) {
        trendFilter = { type: 'line', line: lineName, reason: null };
      } else {
        trendFilter = { type: 'reason', line: lineName, reason: reasonName };
      }
      renderTrend();
      updateDriverHighlights();
    }
  });
}

// ---- Helper functions ----

function updateDriverHighlights() {
  var headers = htmlNode.querySelectorAll('.erp-bar-header');
  for (var i = 0; i < headers.length; i++) headers[i].classList.remove('active');
  var reasons = htmlNode.querySelectorAll('.erp-bar-reason');
  for (var i = 0; i < reasons.length; i++) reasons[i].classList.remove('active');

  if (trendFilter.type === 'line') {
    var h = htmlNode.querySelector('.erp-bar-header[data-line="' + trendFilter.line + '"]');
    if (h) h.classList.add('active');
  } else if (trendFilter.type === 'reason') {
    var r = htmlNode.querySelector('.erp-bar-reason[data-line="' + trendFilter.line + '"][data-reason="' + trendFilter.reason + '"]');
    if (r) r.classList.add('active');
  }
}

function renderTrend() {
  var el = htmlNode.querySelector.bind(htmlNode);
  var filtered = allTrendRows;
  var filterLabel = 'All Lines';

  if (trendFilter.type === 'line' && trendFilter.line) {
    filtered = allTrendRows.filter(function(r) { return r.line_name === trendFilter.line; });
    filterLabel = trendFilter.line;
  } else if (trendFilter.type === 'reason' && trendFilter.line && trendFilter.reason) {
    filtered = allTrendRows.filter(function(r) { return r.line_name === trendFilter.line && r.reason === trendFilter.reason; });
    filterLabel = trendFilter.line + ' \u2014 ' + trendFilter.reason;
  }

  var byWeek = {};
  filtered.forEach(function(r) {
    var ws = r.week_start;
    if (!byWeek[ws]) byWeek[ws] = { week_start: ws, cost: 0 };
    byWeek[ws].cost += (r.downtime_cost || 0) + (r.scrap_cost || 0);
  });
  var weeks = Object.values(byWeek).sort(function(a,b) { return a.week_start < b.week_start ? -1 : 1; });

  el('#trend-filter-label').textContent = '(' + filterLabel + ' \u2014 Downtime Cost in \u20ac)';
  el('#trend-reset').style.display = trendFilter.type === 'all' ? 'none' : 'block';

  var maxWeek = 1;
  weeks.forEach(function(w) { if (w.cost > maxWeek) maxWeek = w.cost; });

  var trendHtml = '';
  var labelHtml = '';
  weeks.forEach(function(w, i) {
    var h = Math.max((w.cost / maxWeek * 100), 3);
    var isLast = i === weeks.length - 1;
    trendHtml += '<div class="erp-trend-bar' + (isLast ? ' current' : '') + '" style="height:' + h + '%">';
    trendHtml += '<span class="erp-trend-bar-val">' + fmt(w.cost) + '</span>';
    trendHtml += '</div>';
    var d = new Date(w.week_start);
    labelHtml += '<span>' + d.getDate() + ' ' + monthNames[d.getMonth()] + '</span>';
  });
  el('#trend-bars').innerHTML = trendHtml || '<div style="color:#9ca3af;text-align:center;width:100%">No trend data</div>';
  el('#trend-labels').innerHTML = labelHtml;
}

// ---- Main render (only updates data, no event binding) ----

htmlNode._render = function() {
  var now = new Date();
  var el = htmlNode.querySelector.bind(htmlNode);
  el('#erp-time').textContent = 'Updated ' + now.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});
  el('#erp-footer-time').textContent = 'Generated: ' + now.toLocaleString();
  el('#erp-site-label').textContent = '';

  var totalS = findSeries(data, 'total_loss');
  var prevS = findSeries(data, 'prev_period_loss');
  var lineS = findSeries(data, 'cost_by_line');
  var incS = findSeries(data, 'top_incidents');
  var trendS = findSeries(data, 'weekly_trend');
  var prodS = findSeries(data, 'production_value');
  var evidS = findSeries(data, 'evidence_detail');

  var total = getField(totalS, 'total_loss') || 0;
  var prev = getField(prevS, 'prev_loss') || 0;
  var prodValue = getField(prodS, 'production_value') || 1;

  el('#kpi-total').textContent = fmtFull(total);
  el('#kpi-total-sub').textContent = 'Period total';
  var tickerHtml = '';
  for (var i = 0; i < 30; i++) {
    var h = Math.max(4, Math.random() * 28 + (total > prevTotal ? 8 : 0));
    tickerHtml += '<span class="erp-ticker-bar" style="height:' + h + 'px;animation-delay:' + (i * 0.07) + 's"></span>';
  }
  el('#kpi-ticker').innerHTML = tickerHtml;
  prevTotal = total;

  var delta = total - prev;
  var deltaEl = el('#kpi-delta');
  if (prev > 0) {
    var deltaPct = ((delta / prev) * 100).toFixed(0);
    deltaEl.textContent = (delta >= 0 ? '+' : '') + fmt(delta);
    deltaEl.className = 'erp-kpi-value ' + (delta > 0 ? 'red' : 'green');
    el('#kpi-delta-sub').innerHTML = '<span class="erp-kpi-badge ' + (delta > 0 ? 'erp-badge-red' : 'erp-badge-green') + '">' + (delta >= 0 ? '\u2191' : '\u2193') + ' ' + Math.abs(deltaPct) + '% vs prior period</span>';
  } else {
    deltaEl.textContent = '--';
    deltaEl.className = 'erp-kpi-value';
    el('#kpi-delta-sub').textContent = 'No prior period data';
  }

  var pctEl = el('#kpi-pct');
  if (prodValue <= 1) {
    pctEl.textContent = 'N/A';
    pctEl.className = 'erp-kpi-value';
    el('#kpi-pct-sub').textContent = 'No production orders in period';
  } else {
    var pct = (total / prodValue * 100);
    pctEl.textContent = pct.toFixed(1) + '%';
    pctEl.className = 'erp-kpi-value ' + (pct > 5 ? 'red' : pct > 2 ? 'amber' : 'green');
    el('#kpi-pct-sub').textContent = 'of ' + fmtFull(prodValue) + ' output value';
  }

  var dayOfMonth = now.getDate();
  var daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
  var projected = dayOfMonth > 0 ? (total / dayOfMonth * daysInMonth) : 0;
  el('#kpi-proj').textContent = fmtFull(projected);
  el('#kpi-proj').className = 'erp-kpi-value red';
  el('#kpi-proj-sub').textContent = 'Based on ' + dayOfMonth + '/' + daysInMonth + ' days elapsed';

  // Cost drivers
  var lineRows = getRows(lineS);
  var byLine = {};
  lineRows.forEach(function(r) {
    if (!byLine[r.line_name]) byLine[r.line_name] = { total: 0, reasons: [] };
    byLine[r.line_name].total += r.impact || 0;
    byLine[r.line_name].reasons.push(r);
  });
  var lineKeys = Object.keys(byLine).sort(function(a,b) { return byLine[b].total - byLine[a].total; });
  var maxImpact = lineKeys.length > 0 ? byLine[lineKeys[0]].total : 1;

  var driverHtml = '';
  lineKeys.forEach(function(line, idx) {
    var pctW = Math.max((byLine[line].total / maxImpact * 100), 2);
    var c = colors[idx % colors.length];
    var reasons = byLine[line].reasons.sort(function(a,b) { return (b.impact||0) - (a.impact||0); });
    driverHtml += '<div class="erp-bar-container" data-line="' + line + '">';
    driverHtml += '<div class="erp-bar-header" data-action="toggle-line" data-line="' + line + '">';
    driverHtml += '<span class="erp-bar-name"><span class="erp-bar-chevron">&#9654;</span> ' + line + '</span>';
    driverHtml += '<span class="erp-bar-value">' + fmtFull(byLine[line].total) + '</span>';
    driverHtml += '</div>';
    driverHtml += '<div class="erp-bar-track" style="margin:0 8px"><div class="erp-bar-fill" style="width:' + pctW + '%;background:' + c + '"></div></div>';
    driverHtml += '<div class="erp-bar-reasons collapsed" data-reasons-for="' + line + '">';
    reasons.forEach(function(r) {
      var cat = r.category || 'Unknown';
      driverHtml += '<div class="erp-bar-reason" data-action="select-reason" data-line="' + line + '" data-reason="' + r.reason + '">';
      driverHtml += '<span><span class="erp-cat-badge erp-cat-' + cat + '">' + cat + '</span> ' + r.reason + '</span>';
      driverHtml += '<span>' + fmtFull(r.impact||0) + '</span>';
      driverHtml += '</div>';
    });
    driverHtml += '</div></div>';
  });
  el('#cost-drivers').innerHTML = driverHtml || '<div style="color:#9ca3af;padding:20px;text-align:center">No cost data</div>';

  // Store trend data and render
  allTrendRows = getRows(trendS);
  renderTrend();
  updateDriverHighlights();

  // Top incidents
  var incidents = getRows(incS);
  var incHtml = '';
  incidents.forEach(function(inc) {
    var cat = inc.category || 'Unknown';
    var rate = recoveryRates[cat] || 0.50;
    var recoveryVal = Math.round((inc.projected_monthly || 0) * rate);
    incHtml += '<tr>';
    incHtml += '<td>' + (inc.line_name||'-') + '</td>';
    incHtml += '<td>' + (inc.reason||'-') + '</td>';
    incHtml += '<td><span class="erp-cat-badge erp-cat-' + cat + '">' + cat + '</span></td>';
    incHtml += '<td class="num">' + (inc.occurrences||0) + '</td>';
    incHtml += '<td class="num">' + (inc.total_min||0) + ' min</td>';
    incHtml += '<td class="num impact">' + fmtFull(inc.total_impact||0) + '</td>';
    incHtml += '<td class="num impact">' + fmtFull(inc.projected_monthly||0) + '</td>';
    incHtml += '<td class="num recovery">\u2192 ' + fmtFull(recoveryVal) + ' <span style="font-size:10px;color:#9ca3af">(' + Math.round(rate*100) + '%)</span></td>';
    incHtml += '</tr>';
  });
  el('#incidents-body').innerHTML = incHtml || '<tr><td colspan="8" style="text-align:center;color:#9ca3af;padding:20px">No data</td></tr>';

  // Evidence
  var evidence = getRows(evidS);
  var evHtml = '';
  evidence.forEach(function(ev) {
    var cat = ev.category || 'Unknown';
    var ts = ev.timestamp ? new Date(ev.timestamp) : null;
    var tsStr = ts ? ts.toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}) : '-';
    evHtml += '<tr>';
    evHtml += '<td>' + tsStr + '</td>';
    evHtml += '<td>' + (ev.line_name||'-') + '</td>';
    evHtml += '<td>' + (ev.machine||'-') + '</td>';
    evHtml += '<td>' + (ev.batch||'-') + '</td>';
    evHtml += '<td>' + (ev.reason||'-') + '</td>';
    evHtml += '<td><span class="erp-cat-badge erp-cat-' + cat + '">' + cat + '</span></td>';
    evHtml += '<td class="num">' + (ev.duration_min||0) + ' min</td>';
    evHtml += '<td class="num impact">' + fmtFull(ev.impact||0) + '</td>';
    evHtml += '</tr>';
  });
  el('#evidence-body').innerHTML = evHtml || '<tr><td colspan="8" style="text-align:center;color:#9ca3af;padding:20px">No events</td></tr>';
};

var prevTotal = 0;
htmlNode._render();
